const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const XS = [301, 829, 1357, 1885, 2413];

function frame(x, content, bg = '#fff', shadow = true) {
  return `${shadow ? `<rect x="${x}" y="270" width="486" height="864" fill="${bg}" filter="url(#shadow)"/>` : ''}
  <svg x="${x}" y="270" width="486" height="864" viewBox="0 0 486 864" overflow="hidden">${content}</svg>`;
}

function board(o) {
  const labels = o.labels.map((label, i) => `<text x="${XS[i]}" y="1200">${String(i + 1).padStart(2, '0')} — ${label}</text>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="3200" height="3200" viewBox="0 0 3200 3200">
  <defs>
    <filter id="shadow" x="-20%" y="-20%" width="140%" height="150%"><feDropShadow dx="0" dy="18" stdDeviation="16" flood-color="${o.shadow || '#101010'}" flood-opacity="0.28"/></filter>
    ${o.defs || ''}
  </defs>
  <rect width="3200" height="3200" fill="${o.boardBg}"/>${o.boardDecor || ''}<rect x="0" y="0" width="44" height="1400" fill="${o.accent}"/>
  <text x="150" y="88" font-family="${o.labelFont || 'Arial, sans-serif'}" font-size="32" font-weight="900" letter-spacing="4" fill="${o.accent}">PROPUESTA ${o.num} · VIDEO 11</text>
  <text x="150" y="170" font-family="${o.titleFont || 'Arial Black, Arial, sans-serif'}" font-size="${o.titleSize || 64}" font-weight="900" letter-spacing="${o.titleSpacing || -3}" fill="${o.boardFg}">${o.title}</text>
  <text x="3030" y="98" text-anchor="end" font-family="${o.labelFont || 'Arial, sans-serif'}" font-size="22" font-weight="900" fill="${o.boardFg}">5 MOMENTOS · 9:16</text>
  <text x="3030" y="145" text-anchor="end" font-family="${o.labelFont || 'Arial, sans-serif'}" font-size="18" font-weight="800" letter-spacing="2" fill="${o.metaColor || o.accent}">${o.meta}</text>
  <line x1="150" y1="223" x2="3030" y2="223" stroke="${o.rule || o.boardFg}" stroke-width="5"/>
  ${o.frames.map((c, i) => frame(XS[i], c.content, c.bg, c.shadow !== false)).join('\n')}
  <g font-family="${o.labelFont || 'Arial, sans-serif'}" font-size="20" font-weight="900" letter-spacing="2" fill="${o.boardFg}">${labels}</g>
  <text x="301" y="1264" font-family="${o.labelFont || 'Arial, sans-serif'}" font-size="24" font-weight="700" fill="${o.boardFg}">${o.summary}</text>
  <text x="2899" y="1322" text-anchor="end" font-family="${o.labelFont || 'Arial, sans-serif'}" font-size="18" font-weight="700" letter-spacing="2" fill="${o.metaColor || o.accent}">TABLERO DE APROBACIÓN · LOS CINCO MARCOS SON LAS PANTALLAS PROPUESTAS</text>
</svg>`;
}

